-- 五代虚构演示数据，共36人。先运行 schema.sql 和 extensions.sql 并注册实际管理账号。
-- 将末尾 CALL 中的 demo_admin 改为已注册的用户名。每次调用创建一个新家族。
SET NAMES utf8mb4;
DELIMITER $$
CREATE PROCEDURE zongmai_seed_demo_v1(IN owner_username VARCHAR(64))
BEGIN
  DECLARE owner_id BIGINT;
  DECLARE family_id_value BIGINT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SELECT id INTO owner_id FROM sys_user WHERE username=owner_username AND status='ACTIVE';
  IF owner_id IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Register the owner account first'; END IF;
  START TRANSACTION;
  SET family_id_value=LAST_INSERT_ID();
  SET @zongmai_p0=LAST_INSERT_ID();
  SET @zongmai_p1=LAST_INSERT_ID();
  SET @zongmai_p2=LAST_INSERT_ID();
  SET @zongmai_p3=LAST_INSERT_ID();
  SET @zongmai_p4=LAST_INSERT_ID();
  SET @zongmai_p5=LAST_INSERT_ID();
  SET @zongmai_p6=LAST_INSERT_ID();
  SET @zongmai_p7=LAST_INSERT_ID();
  SET @zongmai_p8=LAST_INSERT_ID();
  SET @zongmai_p9=LAST_INSERT_ID();
  SET @zongmai_p10=LAST_INSERT_ID();
  SET @zongmai_p11=LAST_INSERT_ID();
  SET @zongmai_p12=LAST_INSERT_ID();
  SET @zongmai_p13=LAST_INSERT_ID();
  SET @zongmai_p14=LAST_INSERT_ID();
  SET @zongmai_p15=LAST_INSERT_ID();
  SET @zongmai_p16=LAST_INSERT_ID();
  SET @zongmai_p17=LAST_INSERT_ID();
  SET @zongmai_p18=LAST_INSERT_ID();
  SET @zongmai_p19=LAST_INSERT_ID();
  SET @zongmai_p20=LAST_INSERT_ID();
  SET @zongmai_p21=LAST_INSERT_ID();
  SET @zongmai_p22=LAST_INSERT_ID();
  SET @zongmai_p23=LAST_INSERT_ID();
  SET @zongmai_p24=LAST_INSERT_ID();
  SET @zongmai_p25=LAST_INSERT_ID();
  SET @zongmai_p26=LAST_INSERT_ID();
  SET @zongmai_p27=LAST_INSERT_ID();
  SET @zongmai_p28=LAST_INSERT_ID();
  SET @zongmai_p29=LAST_INSERT_ID();
  SET @zongmai_p30=LAST_INSERT_ID();
  SET @zongmai_p31=LAST_INSERT_ID();
  SET @zongmai_p32=LAST_INSERT_ID();
  SET @zongmai_p33=LAST_INSERT_ID();
  SET @zongmai_p34=LAST_INSERT_ID();
  SET @zongmai_p35=LAST_INSERT_ID();
  UPDATE family SET ancestor_person_id=@zongmai_p0 WHERE id=family_id_value;
  COMMIT;
  SELECT family_id_value AS created_family_id;
END$$
DELIMITER ;
CALL zongmai_seed_demo_v1('demo_admin');
DROP PROCEDURE zongmai_seed_demo_v1;
